    cols = len(input_grid[0])
    result = [[b for b in row] for row in input_grid]  # Start with a copy

    for r in range(rows):
        for c in range(cols):
            # Only transform background cells (9s)
            if input_grid[r][c] == 9:
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            val = input_grid[nr][nc]
                            neighbors.append(val)

                # Get unique non-background neighbors
                non_bg = set(n for n in neighbors if n != 9)

                if non_bg:
                    if 1 in non_bg:
                        result[r][c] = 7
                    elif non_bg & {2, 6, 8}:
                        result[r][c] = 4
                    # else: no 1, no 2/6/8, should be replaced but shouldn't happen

    return result

